import{_ as i,l as n,o as e,c as s,v as t,p as E,x as r,d as l,i as p,S as B}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"止损与时间止损","description":"","frontmatter":{"title":"止损与时间止损","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/statarb-stops.md","filePath":"quant/statarb-stops.md","lastUpdated":1789023840000}'),d={name:"quant/statarb-stops.md"};function h(A,a,m,c,C,_){const o=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="止损与时间止损" tabindex="-1">止损与时间止损 <a class="header-anchor" href="#止损与时间止损" aria-label="Permalink to &quot;止损与时间止损&quot;">​</a></h1><div class="epigraph"><p>止损规则能否「止住损失」，取决于价格是回归、趋势还是带跳的混合；在随机游走上机械止损往往只是把左尾提前实现，并额外支付一笔交易费用。</p><footer>—— Kaminski &amp; Lo, When Do Stop-Loss Rules Stop Losses?, Journal of Financial Markets, 2014</footer></div><p><a href="/quant/kelly-sizing">上一课</a>把仓位写成扣费后的对数增长；分数 Kelly 降低的是破产与强平风险，不创造保证复利。仓位定了，还要决定何时离场。缺口是三种常见离场如何互相干扰：价差回到均值、价格止损、时间止损。Kaminski–Lo 表明止损的期望依赖 DGP——回归过程上机械止损常有害，趋势上或有益；残差策略默认更接近前者，止损是对破裂的保险。GGR 期末强平是时间止损，会在价差最宽时成交。本课写优先级必须预先写死，不重推 \\(f^\\ast\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>开仓之后，路径有三种结束方式。回归离场：这是策略的假设兑现。价格止损：承认假设错了或错得太久，用一个 \\(z\\) 或亏损百分比切掉。时间止损：无论 \\(z\\) 如何，到期离场，避免把资本锁在慢死亡的价差里。问题是这三种规则在同一条 OU 加跳跃的路径上互相干扰。过紧的价格止损会在 OU 的正常波动里反复止出，把正期望交易切成负期望的往返；过松则在破裂里变成「没有止损」。时间止损会在价差最宽、流动性最差的日历日强制成交，冲击最大。</p><p>Kaminski–Lo 的核心不是推荐某一个百分比，而是：止损是一个非线性滤波器，其期望取决于数据生成过程。统计套利文档必须声明自己假设的 DGP，再选规则。若你相信残差是 OU，价格止损在纯扩散上通常降低期望；你仍然可能要它，因为真实 DGP 含体制转换，见<a href="/quant/cointegration-break">协整破裂</a>。止损此时买的是对模型误设的保险，保费是回归策略的部分期望。</p><h3 id="时间止损不是免费的风险控制" tabindex="-1">时间止损不是免费的风险控制 <a class="header-anchor" href="#时间止损不是免费的风险控制" aria-label="Permalink to &quot;时间止损不是免费的风险控制&quot;">​</a></h3><p>GGR 在交易期末强平，使样本里每对的最大持有期有上界，便于统计，也避免无限期等待。代价是：未回归的对往往是「错了的对」，强平实现的是选择偏差后的亏损腿，而且许多 vintage 在同一天到期会制造额外的同期冲击。把时间止损从 6 个月改成 10 日，策略从中期相对价值变成短持有反转，成本结构完全不同，不能沿用 RFS 2006 的扣费结果。</p><p><span class="marginnote">盘中止损若用收盘规则去回测，会忽略缺口：隔夜跳空直接穿过止损价，实现损失大于设定。规则应写成「触及或跳过则次日中点离场」，并把跳过的额外损失计入期望。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把离场写成优先级明确的状态机。例如：破裂检测（滚动 \\(\\beta\\) 失稳或 Gregory–Hansen 型诊断）&gt; 价格止损 \\(|z|\\gt c_{\\mathrm{stop}}\\) &gt; 时间止损 \\(T_{\\max}\\) &gt; 回归平仓 \\(|z|\\lt c_{\\mathrm{exit}}\\)。优先级反了会出现「已经破裂仍等回归」。\\(c_{\\mathrm{stop}}\\) 应宽于开仓 \\(c\\)，否则开仓即接近止损，信号只贡献换手。\\(T_{\\max}\\) 应按半衰期标定：若 \\(\\hat\\kappa\\) 对应半衰期 5 日，\\(T_{\\max}=60\\) 日意味着你愿意等十几个半衰期，这对纯 OU 过宽、对含破裂的混合分布可能仍不够——因为破裂不按半衰期工作。</p><p>组合层面还要有相关性止损：当许多对同时亏损，说明残差的共同因子回来了，单对止损会在同一天集体触发，变成组合级踩踏。应对是先降总杠杆，再按规则离场，而不是让每一对的止损单去抢已经变薄的账簿。这与 2007 年量化平仓的描述一致：止损与去杠杆同步发生时，价格止损是冲击的来源而不是缓冲。</p><h3 id="再入场与止损距离" tabindex="-1">再入场与止损距离 <a class="header-anchor" href="#再入场与止损距离" aria-label="Permalink to &quot;再入场与止损距离&quot;">​</a></h3><p>止损后是否允许立刻按同一 \\(z\\) 再开仓，决定规则会不会在震荡里刷单。常见冷却期或要求 \\(z\\) 先回到开仓带内再重新武装。再入场等于把一次破裂切成多次止损，成本倍增。止损距离若按开仓后的最大不利偏移（MAE）校准，必须用样本外：用全样本 MAE 的 95% 分位去设止损，会把最坏路径的信息漏进规则。更干净的是按开仓时的 \\(\\hat\\sigma\\) 设 \\(k\\) 倍，并在波动翻倍时自动加宽，避免在高压期被正常波动扫出。</p><p><span class="marginnote">获利了结的 \\(c_{\\mathrm{exit}}\\) 过近，会切断回归的右尾，使盈亏比恶化，再靠提高胜率在样本内补回来。扣费后，高胜率短盈利往往是负期望。平仓阈值与止损阈值要一起优化，且目标必须是净期望，不是胜率。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>纯 OU：最优往往是在偏离处开、在均值附近平，中间的价格止损是对正期望路径的截断。带漂移的错误设定（\\(\\mu\\) 已经跳到新水平）：价格止损与时间止损都是在截断对错误原点的等待，期望改善。动量残差（拥挤平仓）：止损与众人同步，可能卖在最差的流动性上；此时随机止损时间或降低仓位可能优于固定价格线。Kaminski–Lo 对趋势资产的「止损有时有用」在这里对应的是残差动量化的状态，而不是股票指数本身。</p><p>跳空与涨跌停使止损变成期权空头：你以为损失有界，实际交付的是开盘不可成交的缺口。统计套利空腿若遇停牌，止损单无法执行，多腿仍在交易，中性破裂。规则必须包含「单腿无法成交则市价平掉可成交腿并停止开新仓」。这在回测里要用停牌标志，否则历史夏普假设了不存在的流动性。</p><h3 id="成本如何改变止损的符号" tabindex="-1">成本如何改变止损的符号 <a class="header-anchor" href="#成本如何改变止损的符号" aria-label="Permalink to &quot;成本如何改变止损的符号&quot;">​</a></h3><p>无成本时，某些 DGP 下止损的期望可能接近零（随机游走）。有成本时，止损几乎必然贡献负的实施缺口：它增加换手，且触发时价差更宽。因此「有止损的回测夏普更高」若未用有效价差，多半是在无摩擦世界里截断了左尾、却没付截断的手续费。正确的比较是：同一开仓规则，有无止损都扣<a href="/quant/effective-realized-spread">有效价差</a>与冲击，再看净期望与最大回撤。回撤改善但净期望下降，说明你买了保险；是否值得取决于委托约束，不是取决于样本内夏普是否更高。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要把趋势跟随的跟踪止损原样搬到配对上。不要用盘后人工「这次不算」去改历史止损。A 股涨跌停让止损价经常不可达，时间止损更现实，但到期日可能仍停牌。指数与 ETF 套利的离场应优先于结算日或申赎窗口，而不是 \\(z\\) 止损；机制收敛有日历，统计回归没有。</p><p>文档应报告：止损触发频率、触发时的后续价差路径（止损后是否继续走扩，用于检验规则是否过早）、时间止损日的冲击、以及集体触发日的组合亏损。若止损后价差大多回归，规则在纯 OU 上过紧；若止损后继续走扩，规则在买保险上有效，但仍要扣除触发日流动性成本才能谈净效果。</p><p><span class="marginnote">GGR 的期末强平是研究设计也是风险规则。复制时若改成无限持有直到回归，样本内会留下少数极大亏损对，均值可能仍正，但那是未被时间截断的破裂，不能解释成「改进了原文策略」。</span></p>',24)),(e(),E(B,null,{default:r(()=>[p(o,{id:"mermaid-70",class:"mermaid",graph:"flowchart%20TD%0A%20%20OPEN%5B%22%E5%B7%B2%E5%BC%80%E4%BB%93%E7%9A%84%E4%BB%B7%E5%B7%AE%20%2F%20%E6%AE%8B%E5%B7%AE%22%5D%20--%3E%20CHK%7B%22%E7%A0%B4%E8%A3%82%E6%88%96%20%CE%B2%20%E5%A4%B1%E7%A8%B3%3F%22%7D%0A%20%20CHK%20--%3E%7C%E6%98%AF%7C%20FLAT%5B%22%E8%A7%86%E4%B8%BA%E9%94%99%E8%AF%AF%E8%AE%BE%E5%AE%9A%EF%BC%8C%E4%BC%98%E5%85%88%E5%B9%B3%E4%BB%93%22%5D%0A%20%20CHK%20--%3E%7C%E5%90%A6%7C%20ZS%7B%22%7Cz%7C%20%3E%20c_stop%3F%22%7D%0A%20%20ZS%20--%3E%7C%E6%98%AF%7C%20PS%5B%22%E4%BB%B7%E6%A0%BC%E6%AD%A2%E6%8D%9F%EF%BC%8C%E6%8E%A5%E5%8F%97%E8%B7%B3%E7%A9%BA%22%5D%0A%20%20ZS%20--%3E%7C%E5%90%A6%7C%20TM%7B%22%E6%8C%81%E6%9C%89%E6%9C%9F%20%3E%20T_max%3F%22%7D%0A%20%20TM%20--%3E%7C%E6%98%AF%7C%20TS%5B%22%E6%97%B6%E9%97%B4%E6%AD%A2%E6%8D%9F%20%2F%20%E6%9C%9F%E6%9C%AB%E5%BC%BA%E5%B9%B3%22%5D%0A%20%20TM%20--%3E%7C%E5%90%A6%7C%20EX%7B%22%7Cz%7C%20%EF%BC%9C%20c_exit%3F%22%7D%0A%20%20EX%20--%3E%7C%E6%98%AF%7C%20TP%5B%22%E5%9B%9E%E5%BD%92%E7%A6%BB%E5%9C%BA%22%5D%0A%20%20EX%20--%3E%7C%E5%90%A6%7C%20HOLD%5B%22%E7%BB%A7%E7%BB%AD%E6%8C%81%E6%9C%89%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>统计套利离场包括回归平仓、价格止损与时间止损；优先级必须预先写死，破裂检测应高于 \\(z\\) 止损。</li><li>Kaminski–Lo（2014）表明止损的期望依赖 DGP：回归过程上机械止损常有害，趋势上或有益；残差策略默认更接近前者，止损是对破裂的保险而非提高期望的自由午餐。</li><li>GGR 期末强平是时间止损，会在价差最宽时成交；缩短 \\(T_{\\max}\\) 会改变策略类别与成本。</li><li>有交易成本时止损增加换手并常在流动性差时触发；必须用有效价差比较有无止损的净期望与回撤。</li><li>出处：Kaminski and Lo, <em>Journal of Financial Markets</em>, 2014；Gatev, Goetzmann and Rouwenhorst, <em>RFS</em>, 2006；结构转换见 Gregory–Hansen, 1996；拥挤平仓见 Khandani and Lo, 2007。</li></ul>',2))])}const D=i(d,[["render",h]]);export{f as __pageData,D as default};
